        !isfinite(mt_config.capacity_j_k) || mt_config.capacity_j_k <= 0.0 ||
        !isfinite(mt_config.thermal_resistance_k_w) || mt_config.thermal_resistance_k_w <= 0.0 ||
        !isfinite(mt_config.trip_temperature_k) ||
        !isfinite(mt_config.reset_temperature_k) ||
        mt_config.reset_temperature_k >= mt_config.trip_temperature_k ||
        !isfinite((double)mt_config.max_trip_cycles) ||
        mt_config.max_trip_cycles > 1000U) {
        valid_data = 0;
    }
