    mt_output.mode = MT_FAULT;
    mt_output.applied_voltage_v = 0.0;
    mt_output.winding_temperature_k = mt_state.winding_temperature_k;
    mt_output.heating_w = 0.0;
    mt_output.cooling_w = 0.0;
