double t_curr = mt_state.winding_temperature_k;
double t_amb = tel->ambient_temperature_k;
double dt = tel->dt_s;
double r = mt_config.resistance_ohm;
double c = mt_config.capacity_j_k;
double rth = mt_config.thermal_resistance_k_w;

double heating_w = (limited_voltage * limited_voltage) / r;
double cooling_w = (t_curr - t_amb) / rth;
double t_next = t_curr + ((heating_w - cooling_w) * dt) / c;

mt_output.heating_w = heating_w;
mt_output.cooling_w = cooling_w;

