mt_mode_t effective_mode = mt_state.mode;
if (effective_mode == MT_OFF) {
    effective_mode = MT_DRIVE;
}

switch (effective_mode) {
    case MT_DRIVE:
        if (t_next >= mt_config.trip_temperature_k) {
            if (mt_config.max_trip_cycles == 0 || mt_state.trip_count < mt_config.max_trip_cycles) {
                next_mode = MT_COOL;
                mt_state.trip_count++;
                applied_voltage = 0.0;
            } else {
                next_mode = MT_FAULT;
                applied_voltage = 0.0;
            }
        } else {
            next_mode = MT_DRIVE;
            applied_voltage = limited_voltage;
        }
        break;
    case MT_COOL:
        if (t_next > mt_config.reset_temperature_k) {
            next_mode = MT_COOL;
            applied_voltage = 0.0;
        } else {
            next_mode = MT_DRIVE;
            applied_voltage = 0.0;
        }
        break;
    case MT_FAULT:
        next_mode = MT_FAULT;
        applied_voltage = 0.0;
        break;
    default:
        next_mode = MT_FAULT;
        applied_voltage = 0.0;
        break;
}

// Step 7: Update Outputs and State
mt_output.mode = next_mode;
mt_output.applied_voltage_v = applied_voltage;
mt_output.winding_temperature_k = t_next;
mt_state.mode = next_mode;
mt_state.winding_temperature_k = t_next;

